const app=document.querySelector('#app');
function shell(title,kicker,body){return `<div class="pageTitle"><div class="eyebrow">${kicker}</div><h1 class="display">${title}</h1></div>${body}`}
function home(){return `<section class="hero" id="home"><div class="heroCopy"><div class="eyebrow">A DIFFERENT WAY INTO THE GAME</div><h1 class="display">I became a Chelsea fan because of Eden Hazard.</h1><p class="lede">Today, the next Eden Hazard might find you before you ever find him.</p><a class="cta" href="#journey">Follow the fan journey ↗</a></div><div class="photo"></div></section><div class="band">DISCOVERY. ENGAGEMENT. PARTICIPATION. IDENTITY. LOYALTY.</div>
<section class="section"><div class="num">01 / HOW IT STARTED</div><div class="grid2"><div><div class="eyebrow">PERSONAL EXPERIENCE ≠ ACADEMIC EVIDENCE</div><h2 class="question">That was my fan journey. What happens when TikTok can initiate millions like it?</h2></div><div><p class="lede">Hazard got my attention. Chelsea became my team. In between were the matches, the players, the culture and the feeling that this club somehow belonged to me.</p><div class="card">EDEN HAZARD → PLAYER INTEREST → WATCHED CHELSEA → LEARNED THE TEAM → FOLLOWED THE CULTURE → IDENTIFIED WITH THE CLUB → CHELSEA FAN</div></div></div><div class="take"><b>THE QUESTION BEHIND EVERYTHING</b><p>${rq}</p><strong>Or, in normal-person language: How does somebody go from “Who the hell is that?” to “That’s my team”?</strong></div></section>
<section class="section dark"><div class="num">02 / MORE THAN A SEAT</div><h2 class="display">FANDOM HAS MORE ADDRESSES NOW.</h2><p class="lede">The stadium. The couch. The group chat. The feed. What does being a sports fan actually look like in 2026?</p><div class="grid2"><div class="card">IN THE STANDS<br><br>Watch parties • Full games • Live moments</div><div class="card">TOGETHER, ELSEWHERE<br><br>Fan edits • Fantasy leagues • Highlights • Second screens • Group chats</div></div></section>
<section class="section blue"><div class="num">03 / THE PROPOSED FRAMEWORK</div><h2 class="display">A VIEW IS JUST THE OPENING WHISTLE.</h2><p>Five connected stages. Plenty of detours. Click a stage.</p><div class="journey">${stages.map((s,i)=>`<div class="stage" onclick="this.classList.toggle('active')"><span>0${i+1} ↗</span><b>${s[0]}</b><p>${s[1]}</p></div>`).join('')}</div><div class="take"><b>JG'S TAKE · EDITORIAL COPY</b><p>Sports fans say “we won” after contributing absolutely nothing to the victory. That level of identification is exactly why fandom is fascinating.</p></div></section>
<section class="section"><div class="num">04 / A DIFFERENT PERSPECTIVE</div><h2 class="display">EMPTY SEATS.<br>FULL FEEDS.</h2><p class="lede">The stands tell one story. The feed tells another. A photograph cannot tell us how many people care.</p><div class="grid2"><div class="card"><h3>THE VISIBLE SEAT</h3><p>Attendance is one expression of fandom. It is not the only one.</p></div><div class="card"><h3>THE SHARED PLACE</h3><p>Is the fan in Row 4 inherently “more of a fan” than someone 1,000 miles away?</p></div></div></section>
<section class="tools"><a class="tool yellow" href="#strategy"><div class="eyebrow">FROM THE QUESTION TO THE GAME PLAN</div><h3>DON'T JUST CHASE THE SCROLL.</h3><p>Build a practical starting point for your content strategy.</p></a><a class="tool blue" href="#research"><div class="eyebrow">INSIDE THE LAB</div><h3>RESEARCH WITH SOMETHING TO DO.</h3><p>Explore the research.</p></a><a class="tool" href="#starting"><div class="eyebrow">THE FINAL TEAM SHEET</div><h3>JOHN'S STARTING XI</h3><p>Eleven positions reserved for eleven research-supported principles.</p></a></section>`}
function journey(){return shell('HOW FANDOM FOUND YOU','THE FAN JOURNEY',`<section class="section"><div class="grid2"><div><h2 class="display">THEN</h2><div class="card">Family<br>Geography<br>Television<br>Local team<br>Favorite player<br>Newspaper<br>SportsCenter<br>Friends<br>Going to games</div></div><div><h2 class="display">NOW</h2><div class="card">For You Page<br>Athlete clips<br>Creators<br>Highlights<br>Memes<br>Algorithms<br>Fantasy sports<br>Group chats<br>Fan edits<br>Viral moments</div></div></div><h2 class="question">What happens when geography is no longer the gatekeeper of fandom?</h2></section><section class="section dark"><div class="eyebrow">BEFORE THE FYP, THERE WAS HAZARD.</div><h2 class="display">ONE PLAYER. A WHOLE NEW WORLD.</h2><p class="lede">My path happened organically. TikTok raises a much bigger question: what happens when a recommendation system repeatedly places athletes, teams and sports in front of someone who never went looking for them?</p></section>`)}
function strategy(){return shell('DON’T JUST CHASE THE SCROLL.','STRATEGY BUILDER',`<section class="section blue"><h2>WHO ARE YOU?</h2><div class="chips">${['Professional Team','College Athletics','League','Athlete','Sports Brand','Sports Media Company'].map(x=>`<button onclick="pick(this)">${x}</button>`).join('')}</div><h2>WHO ARE YOU TRYING TO REACH?</h2><div class="chips">${['Existing fans','Casual fans','Young fans','Fans outside your market','Fans of an athlete','People unfamiliar with your sport'].map(x=>`<button onclick="pick(this)">${x}</button>`).join('')}</div><h2>WHAT DO YOU WANT?</h2><div class="chips">${stages.map(x=>`<button onclick="pick(this)">${x[0]}</button>`).join('')}<button onclick="pick(this)">Attendance</button><button onclick="pick(this)">Viewership</button></div><button class="cta" onclick="document.querySelector('#plan').style.display='block'">BUILD MY GAME PLAN ↗</button><div id="plan" class="take" style="display:none"><b>YOUR GAME PLAN</b><p>Start with discovery-friendly short-form content, then give viewers a clear reason to return, participate and identify. Research-supported recommendations will replace provisional guidance as John's thesis findings are completed.</p></div></section>`)}
function research(){return shell('RESEARCH WITH SOMETHING TO DO.','RESEARCH & INSIGHTS',`<section class="section"><h2 class="question">${rq}</h2><div class="grid2"><div class="card"><b>WHAT THE RESEARCH SAYS</b><p>Thesis evidence pending. This component is ready for John's literature review and findings.</p></div><div class="card"><b>JG'S TAKE</b><p>Attention is useful. Attention pretending to be loyalty is where marketers can get themselves in trouble.</p></div></div></section><section class="section dark"><h2 class="display">CONGRATS ON THE VIEWS. NOW WHAT?</h2><div class="grid2"><div class="card"><h2>1,400,000 views</h2><h2>87,000 likes</h2><h2>6,400 shares</h2></div><div class="card">Did they follow?<br>Did they come back?<br>Did they watch?<br>Did they participate?<br>Did they care?<br>Did they attend?<br>Are they still here six months later?</div></div><h2 class="question">ATTENTION ≠ LOYALTY</h2></section>`)}
function content(){return shell('THE CONTENT LAB','TEST THE APPROACH',`<section class="section blue"><p class="lede">Fourteen content formats. Different ways into fandom.</p><div class="chips">${['Highlights','Athlete personality',"Mic'd up",'Behind the scenes','Fan reactions','Memes','History','Nostalgia','Rivalries','Educational content','Creator collaborations','UGC','Storytelling','Trends'].map(x=>`<button onclick="lab(this)">${x}</button>`).join('')}</div><div id="lab" class="take"><b>SELECT A CONTENT FORMAT</b><p>See its likely fan stage, audience, upside, downside, useful metrics and future research support.</p></div></section>`)}
function starting(){return shell("JOHN'S STARTING XI",'THE FINAL TEAM SHEET',`<section class="section dark"><h2>11 RULES FOR WINNING THE NEXT SPORTS FAN</h2><p>Each position is reserved for a research-supported principle from the final thesis.</p><div class="pitch">${Array.from({length:11},(_,i)=>`<div class="player" onclick="alert('0${i+1} — Research Finding\\nWaiting for John’s research data.')">${String(i+1).padStart(2,'0')}<br>FINDING</div>`).join('')}</div></section>`)}
function why(){return shell("FANS AREN'T JUST THE AUDIENCE. PARTICIPANTS.",'PARTICIPATORY CULTURE',`<section class="section"><p class="lede">Fan edits. Reaction videos. Memes. Duets. Predictions. Fantasy sports. Debates. Creator analysis. Inside jokes. Traditions.</p><h2 class="question">IF YOUR FAVORITE PLAYER GETS TRADED TOMORROW, WHERE DOES YOUR LOYALTY GO?</h2><div class="quiz"><button onclick="pick(this)">The player</button><button onclick="pick(this)">The team</button><button onclick="pick(this)">Both</button><button onclick="pick(this)">Depends who traded him</button></div></section><section class="section dark"><div class="eyebrow">THE PERSON ASKING</div><h2 class="display">PLAYER. COACH. FAN. MARKETER.</h2><p class="lede">Four perspectives. One question about who comes next.</p></section>`)}
function thesis(){return shell("YES, THERE'S AN ACTUAL THESIS.",'THE THESIS',`<section class="section"><div class="academic"><h3>Research Question</h3><p>${rq}</p>${['Abstract','Literature Review Overview','Methodology','Findings','Discussion','Limitations','Future Research','References'].map(x=>`<h3>${x}</h3><div class="placeholder">Waiting for John's thesis material.</div>`).join('')}<p class="muted">For anyone who looked at the $17 hot dog graphic and thought, “But where's the methodology?” Welcome.</p></div></section>`)}
function sources(){return shell('SOURCES & IMAGE CREDITS','RESEARCH INTEGRITY',`<section class="section"><div class="academic"><p>No invented citations. No invented statistics. No invented findings.</p><div class="placeholder">Full academic references and licensed image credits will be added as thesis materials are finalized.</div><p>No affiliation with TikTok, any athlete, team or league.</p></div></section>`)}
function pick(el){el.parentElement.querySelectorAll('button').forEach(b=>b.classList.remove('active'));el.classList.add('active')}function lab(el){document.querySelectorAll('.chips button').forEach(b=>b.classList.remove('active'));el.classList.add('active');document.querySelector('#lab').innerHTML=`<b>${el.textContent.toUpperCase()}</b><p><strong>Best fan stage:</strong> Discovery / Engagement</p><p><strong>Why it could work:</strong> Creates a low-friction entry point into the sport or athlete story.</p><p><strong>Research support:</strong> Waiting for John's thesis evidence.</p>`}
function render(){let h=location.hash||'#home';let fn=h.startsWith('#journey')?journey:h.startsWith('#strategy')?strategy:h.startsWith('#research')?research:h.startsWith('#content')?content:h.startsWith('#starting')?starting:h.startsWith('#why')?why:h.startsWith('#thesis')?thesis:h.startsWith('#sources')?sources:home;app.innerHTML=fn();scrollTo(0,0)}window.addEventListener('hashchange',render);render();
